/* имя жителя в падеже: род («для Селога»), дат («к Селогу»), вин («найди Селога»), тв («рядом с Селогом»).
   Женские имена на согласную и имена на «о», «у», «и», «е» не склоняются; пол неизвестен — склоняются лишь имена на «а» и «я». */
function имя180(имя,пол,к){const s=String(имя||"");if(!s||!к||к==="им")return s;const l=s.slice(-1).toLowerCase(),l2=s.slice(-2,-1).toLowerCase(),o=s.slice(0,-1);
 if(l==="а")return o+({род:/[гкхжшщч]/.test(l2)?"и":"ы",дат:"е",вин:"у",тв:/[жшщчц]/.test(l2)?"ей":"ой"}[к]||"а");
 if(l==="я")return o+({род:"и",дат:l2==="и"?"и":"е",вин:"ю",тв:"ей"}[к]||"я");
 if(пол!=="м")return s;
 if(/[бвгджзклмнпрстфхцчшщ]/.test(l))return s+({род:"а",дат:"у",вин:"а",тв:/[жшщчц]/.test(l)?"ем":"ом"}[к]||"");
 if(l==="й"||l==="ь")return o+({род:"я",дат:"ю",вин:"я",тв:"ем"}[к]||l);
 return s;}
