 создать(p,lvl,T){const д=p.дом>=0?lvl.дома180[p.дом]:null;const s=this.ст();
  const t={id:"t"+(++s.n),tpl:T.id,n:T.n,key:p.key,имя:p.имя,пол:p.пол,prof:p.prof,домИм:д?д.n:(p.здание||""),дом:p.дом,кл:Селение180.класс(lvl),
   место:{bx:lvl.bx,by:lvl.by,stype:lvl.stype,имя:(G.place&&G.place.bx===lvl.bx&&G.place.by===lvl.by?G.place.name:"")||safeFn(()=>cellContent(lvl.bx,lvl.by).structure.name,"поселение")},
   i:0,ход:{},ноша:null,ведёт:false,взято:this.сейчас()};
  if(T.кому){const q=safeFn(()=>T.кому(p,д,lvl),null);if(!q||!q.где)return null;t.куда={key:q.key,x:q.где.x,y:q.где.y,n:q.имя};t.кому=q.имя;t.комуПол=q.пол;t.где=q.дома?`дома, ${(lvl.дома180[q.дом]||{}).n||""}`:(q.вне||"неподалёку");}
  if(T.вещьИм)t.вещьИм=T.вещьИм(p);
  t.стадии=safeFn(()=>T.стадии(p,д,lvl,t),null);if(!Array.isArray(t.стадии)||!t.стадии.length)return null;
  if(t.стадии.some(z=>(z.цели&&!z.цели.length)||(z.вид==="нести"&&(!z.откуда||!z.откуда.length||!z.куда||!z.куда.length))))return null;
  t.где0=p.где?{x:p.где.x,y:p.где.y}:null;
  t.текст=T.просьба(p,д||{род:"дома"},t);return t;},
 /* инструмент: каждая группа — «одно из» */
 нетИнстр(T){return (T.инстр||[]).filter(гр=>!гр.some(v=>this.есть(v))).map(гр=>гр.join(" или ").toLowerCase());},
