  if(z.вид==="нести"){if(t.ноша)return z.куда.find(неСделано)||z.куда[0];const p=G.place||{x:0,y:0};return this.ближний(z.откуда,p.x,p.y);}
  if(z.вид==="отдать")return {x:z.кому.x,y:z.кому.y,n:z.кому.n};
  if(z.вид==="принести")return (Number(G.inv[z.ресурс])||0)>=z.сколько&&t.где0?{x:t.где0.x,y:t.где0.y,n:t.имя}:null;
  if(z.вид==="найти")return z.цели.find(c=>!t.ход[c.x+","+c.y])||null;
  if(z.вид==="привести")return t.ведёт?z.куда:z.откуда;
